def next_greater_circular(nums):
    n = len(nums); out = [-1] * n; st = []
    for i in range(2 * n):
        x = nums[i % n]
        while st and nums[st[-1]] < x:
            out[st.pop()] = x
        if i < n: st.append(i)
    return out

