vector<int> nextGreaterElements(vector<int>& a) {
    int n = a.size(); vector<int> out(n, -1), st;
    for (int i = 0; i < 2 * n; i++) {
        int x = a[i % n];
        while (!st.empty() && a[st.back()] < x) { out[st.back()] = x; st.pop_back(); }
        if (i < n) st.push_back(i);
    }
    return out;
}
